import React, { useState } from 'react';

import {
  useNavigate
} from 'react-router-dom';

import {
  useAuth
} from '../../hooks/useAuth';

import {
  useLanguage
} from '../../contexts/LanguageContext';

import {
  toast
} from 'react-toastify';

import {
  FiUser,
  FiLock,
  FiShield,
  FiEye,
  FiEyeOff,
} from 'react-icons/fi';


// ==========================================
// IMPORT LOGO
// ==========================================

import logo from '../layout/SC ACADEMY new.png';


// ==========================================
// ADMIN LOGIN
// ==========================================

const AdminLogin = () => {

  // ==========================================
  // LANGUAGE
  // ==========================================

  const {
    language,
    changeLanguage,
    t,
  } = useLanguage();


  // ==========================================
  // AUTH
  // ==========================================

  const {
    login
  } = useAuth();


  // ==========================================
  // NAVIGATION
  // ==========================================

  const navigate =
    useNavigate();


  // ==========================================
  // STATE
  // ==========================================

  const [
    username,
    setUsername
  ] = useState('');


  const [
    password,
    setPassword
  ] = useState('');


  const [
    loading,
    setLoading
  ] = useState(false);

  const [
    showPassword,
    setShowPassword
  ] = useState(false);


  // ==========================================
  // LOGIN
  // ==========================================

  const handleSubmit = async (e) => {

    e.preventDefault();


    // ------------------------------------------
    // BASIC VALIDATION
    // ------------------------------------------

    if (
      !username.trim() ||
      !password
    ) {

      toast.error(
        t('login.required')
      );

      return;
    }


    setLoading(true);


    try {

      const result =
        await login(
          username.trim(),
          password
        );


      // ========================================
      // LOGIN SUCCESS
      // ========================================

      if (result?.success) {

        toast.success(
          t('login.success')
        );


        navigate(
          '/',
          {
            replace: true
          }
        );

        return;
      }


      // ========================================
      // LOGIN FAILED
      // ========================================

      toast.error(
        result?.error ||
        t('login.failed')
      );


    } catch (error) {

      console.error(
        'Login error:',
        error
      );


      const message =
        error?.response?.data?.detail ||
        error?.response?.data?.message ||
        t('login.error');


      toast.error(
        message
      );


    } finally {

      setLoading(false);

    }

  };


  // ==========================================
  // RENDER
  // ==========================================

  return (
    <div
      className="
        relative min-h-screen w-full overflow-hidden
        flex items-center justify-center
        bg-blue-900 px-4 py-8
      "
      style={{
        backgroundImage:
          "linear-gradient(90deg, rgba(15,23,42,0.92) 0%, rgba(30,64,175,0.82) 45%, rgba(30,58,138,0.66) 100%), url('https://images.unsplash.com/photo-1509062522246-3755977927d7?auto=format&fit=crop&w=2200&q=85')",
        backgroundSize: "cover",
        backgroundPosition: "center",
      }}
    >
      {/* Soft background glow */}
      <div className="absolute inset-0 pointer-events-none">
        <div className="absolute -left-24 -top-24 h-80 w-80 rounded-full bg-blue-300/10 blur-3xl" />
        <div className="absolute -bottom-32 -right-20 h-96 w-96 rounded-full bg-red-300/10 blur-3xl" />
      </div>

      {/* Main login card */}
      <div
        className="
          relative z-10 w-full max-w-[555px]
          overflow-hidden rounded-[30px]
          border border-blue-100
          bg-white/95 shadow-[0_30px_90px_rgba(0,0,0,0.30)]
          backdrop-blur-xl
        "
      >
        {/* Decorative mint circle */}
        <div
          className="
            pointer-events-none absolute -right-20 -top-20
            h-52 w-52 rounded-full
            bg-blue-50/90
          "
        />

        <div className="relative px-8 py-9 sm:px-10 sm:py-11">
          {/* Language switcher */}
          <div
            className="
              absolute right-6 top-6 z-20
              flex items-center gap-1 rounded-full
              border border-blue-200 bg-white/90 p-1
              shadow-sm backdrop-blur
            "
          >
            <button
              type="button"
              onClick={() => changeLanguage("en")}
              disabled={loading}
              className={`
                rounded-full px-3 py-1.5 text-[11px] font-bold
                transition-all duration-200
                ${
                  language === "en"
                    ? "bg-blue-900 text-white shadow"
                    : "text-blue-500 hover:bg-blue-50"
                }
              `}
            >
              EN
            </button>

            <button
              type="button"
              onClick={() => changeLanguage("km")}
              disabled={loading}
              className={`
                rounded-full px-3 py-1.5 text-[11px] font-bold
                transition-all duration-200
                ${
                  language === "km"
                    ? "bg-red-600 text-white shadow"
                    : "text-blue-500 hover:bg-blue-50"
                }
              `}
            >
              ខ្មែរ
            </button>
          </div>

          {/* Logo */}
          <div className="mb-6 flex justify-center">
            <div
              className="
                flex h-[82px] w-[150px] items-center justify-center
                rounded-2xl bg-white px-3
                shadow-sm
              "
            >
              <img
                src={logo}
                alt="SC Academy Logo"
                className="max-h-full w-full object-contain"
              />
            </div>
          </div>

          {/* Heading */}
          <div className="mb-8 text-center">
            <h1
              className="
                text-[32px] font-extrabold tracking-tight
                text-blue-900 sm:text-[36px]
              "
            >
              Welcome Back
            </h1>

            <p className="mt-2 text-[15px] font-medium text-blue-400">
              {t("login.subtitle")}
            </p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-5">
            {/* Registration / Username */}
            <div>
              <label
                htmlFor="admin-username"
                className="sr-only"
              >
                {t("login.username")}
              </label>

              <div className="relative">
                <FiUser
                  size={20}
                  className="
                    pointer-events-none absolute left-5 top-1/2
                    -translate-y-1/2 text-blue-300
                  "
                />

                <input
                  id="admin-username"
                  name="username"
                  type="text"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  placeholder={t("login.usernamePlaceholder")}
                  required
                  disabled={loading}
                  autoComplete="username"
                  autoFocus
                  className="
                    h-[68px] w-full rounded-[17px]
                    border border-blue-200
                    bg-blue-50 pl-14 pr-5
                    text-[16px] font-medium text-blue-900
                    outline-none transition-all duration-200
                    placeholder:text-blue-300
                    focus:border-blue-900
                    focus:bg-white
                    focus:ring-4 focus:ring-blue-100
                    disabled:cursor-not-allowed disabled:opacity-60
                  "
                />
              </div>
            </div>

            {/* Password */}
            <div>
              <label
                htmlFor="admin-password"
                className="sr-only"
              >
                {t("login.password")}
              </label>

              <div className="relative">
                <FiLock
                  size={20}
                  className="
                    pointer-events-none absolute left-5 top-1/2
                    -translate-y-1/2 text-blue-300
                  "
                />

                <input
                  id="admin-password"
                  name="password"
                  type={showPassword ? "text" : "password"}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder={t("login.passwordPlaceholder")}
                  required
                  disabled={loading}
                  autoComplete="current-password"
                  className="
                    h-[68px] w-full rounded-[17px]
                    border border-blue-200
                    bg-blue-50 pl-14 pr-14
                    text-[16px] font-medium text-blue-900
                    outline-none transition-all duration-200
                    placeholder:text-blue-300
                    focus:border-blue-900
                    focus:bg-white
                    focus:ring-4 focus:ring-blue-100
                    disabled:cursor-not-allowed disabled:opacity-60
                  "
                />

                <button
                  type="button"
                  onClick={() => setShowPassword((value) => !value)}
                  disabled={loading}
                  aria-label={showPassword ? "Hide password" : "Show password"}
                  className="
                    absolute right-5 top-1/2
                    -translate-y-1/2
                    text-blue-300 transition-colors
                    hover:text-blue-900
                  "
                >
                  {showPassword ? <FiEyeOff size={20} /> : <FiEye size={20} />}
                </button>
              </div>
            </div>

            {/* Remember / Forgot */}
            <div className="flex items-center justify-between gap-4 px-1">
              <label className="flex cursor-pointer items-center gap-2 text-[15px] font-medium text-slate-700">
                <input
                  type="checkbox"
                  className="
                    h-[18px] w-[18px] rounded border-slate-300
                    accent-emerald-500
                  "
                />
                <span>Remember Me</span>
              </label>

              <button
                type="button"
                onClick={() =>
                  toast.info(
                    language === "km"
                      ? "សូមទាក់ទងអ្នកគ្រប់គ្រងសាលា ដើម្បីកំណត់ Password ឡើងវិញ។"
                      : "Please contact the school administrator to reset your password."
                  )
                }
                className="
                  text-[15px] font-bold text-emerald-500
                  transition-colors hover:text-red-600
                "
              >
                Forgot Password?
              </button>
            </div>

            {/* Login button */}
            <button
              type="submit"
              disabled={loading}
              className={`
                mt-2 flex h-[68px] w-full items-center justify-center
                rounded-[17px]
                bg-gradient-to-r from-red-600 to-red-500
                text-[18px] font-extrabold tracking-wide text-white
                shadow-[0_12px_25px_rgba(220,38,38,0.28)]
                transition-all duration-200
                ${
                  loading
                    ? "cursor-not-allowed opacity-60"
                    : "hover:-translate-y-0.5 hover:shadow-[0_16px_30px_rgba(220,38,38,0.34)] active:translate-y-0"
                }
              `}
            >
              {loading ? (
                <span className="flex items-center gap-3">
                  <span
                    className="
                      h-5 w-5 animate-spin rounded-full
                      border-2 border-white/30 border-t-white
                    "
                  />
                  {t("login.loggingIn")}
                </span>
              ) : (
                <span className="flex items-center gap-2">
                  {t("login.signIn")}
                  <span className="text-xl leading-none">→</span>
                </span>
              )}
            </button>
          </form>

          {/* Security */}
          <div className="mt-7 flex items-center justify-center gap-2 text-xs font-medium text-blue-300">
            <FiShield size={13} />
            <span>{t("login.secureAccess")}</span>
          </div>
        </div>
      </div>

      {/* Footer */}
      <div className="absolute bottom-4 left-0 right-0 z-10 text-center text-xs font-medium text-white/70">
        © 2026 SC Academy School. All rights reserved.
      </div>
    </div>
  );

};


export default AdminLogin;
